files.content:
[hidden] { display: none !important; }

*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --panel: #0f3460;
  --accent: #e94560;
  --text: #f5f5f5;
  --muted: #a0a0b0;
  --pixel-border: 4px solid var(--accent);
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  background-image: radial-gradient(circle at 50% 0%, #2a2a4a 0%, var(--bg) 70%);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.scoreboard {
  background: var(--card);
  border: var(--pixel-border);
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
  padding: 24px;
  width: 100%;
  max-width: 640px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.pixel-title {
  margin: 0;
  text-align: center;
  font-size: 1.5rem;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.teams {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.team {
  background: var(--panel);
  border: 2px solid var(--muted);
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.team-name {
  margin: 0;
  font-size: 1rem;
  letter-spacing: 2px;
  color: var(--muted);
}

.score {
  font-size: 3rem;
  font-weight: 700;
  line-height: 1;
  color: var(--text);
  text-shadow: 3px 3px 0 #000;
  font-variant-numeric: tabular-nums;
}

.score-buttons {
  display: flex;
  gap: 8px;
  width: 100%;
}

button {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  border: 2px solid var(--accent);
  background: var(--bg);
  color: var(--text);
  padding: 10px 12px;
  transition: background 0.1s, transform 0.05s, box-shadow 0.1s;
}

button:hover:not(:disabled) {
  background: var(--accent);
  color: #fff;
}

button:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

button:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: none;
}

button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.score-btn {
  flex: 1;
  min-width: 0;
}

.period {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.period-label {
  font-size: 1rem;
  letter-spacing: 2px;
  color: var(--muted);
}

.period-controls {
  display: flex;
  align-items: center;
  gap: 12px;
}

.period-btn {
  width: 44px;
  height: 44px;
  padding: 0;
  font-size: 1.25rem;
  line-height: 1;
}

.period-value {
  font-size: 1.75rem;
  font-weight: 700;
  min-width: 2ch;
  text-align: center;
  color: var(--accent);
}

.actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.action-btn {
  flex: 1;
  padding: 12px 16px;
  letter-spacing: 1px;
}

.action-btn.reset {
  border-color: var(--muted);
}

.action-btn.reset:hover:not(:disabled) {
  background: var(--muted);
  color: var(--bg);
}

@media (max-width: 420px) {
  .scoreboard {
    padding: 16px;
  }
  .teams {
    grid-template-columns: 1fr;
  }
  .score {
    font-size: 2.5rem;
  }
  .actions {
    flex-direction: column;
  }
}

(function () {
  'use strict';

  var state = {
    scores: { a: 0, b: 0 },
    period: 1,
    history: []
  };

  var els = {
    teamA: document.getElementById('team-a-score'),
    teamB: document.getElementById('team-b-score'),
    period: document.getElementById('period-value'),
    undo: document.getElementById('undo-btn'),
    reset: document.getElementById('reset-btn'),
    periodUp: document.getElementById('period-up'),
    periodDown: document.getElementById('period-down')
  };

  function render() {
    els.teamA.textContent = state.scores.a;
    els.teamB.textContent = state.scores.b;
    els.period.textContent = state.period;
    els.undo.disabled = state.history.length === 0;
    els.periodUp.disabled = state.period >= 4;
    els.periodDown.disabled = state.period <= 1;
  }

  function pushHistory(entry) {
    state.history.push(entry);
  }

  function addScore(team, points) {
    pushHistory({ type: 'score', team: team, points: points });
    state.scores[team] += points;
    render();
  }

  function changePeriod(delta) {
    var next = state.period + delta;
    if (next < 1 || next > 4) return;
    pushHistory({ type: 'period', from: state.period, to: next });
    state.period = next;
    render();
  }

  function undo() {
    if (state.history.length === 0) return;
    var last = state.history.pop();
    if (last.type === 'score') {
      state.scores[last.team] -= last.points;
    } else if (last.type === 'period') {
      state.period = last.from;
    }
    render();
  }

  function reset() {
    state.scores.a = 0;
    state.scores.b = 0;
    state.period = 1;
    state.history = [];
    render();
  }

  document.querySelectorAll('.score-btn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      addScore(btn.dataset.team, parseInt(btn.dataset.points, 10));
    });
  });

  els.periodUp.addEventListener('click', function () { changePeriod(1); });
  els.periodDown.addEventListener('click', function () { changePeriod(-1); });
  els.undo.addEventListener('click', undo);
  els.reset.addEventListener('click', reset);

  render();
})();
